    /// [`OutputFormat::Text`] is a TOON 4.4 root object, with no trailing newline: `error: <code label>`, `message: …`
    /// (quoted per §7.2), the inline `causes[N]: …` array when there are causes, `exit_code: 1`, then the inline
    /// `help[N]: …` array and the `recovery[1]{tool,params,reason}:` table when present.
    ///
    /// [`OutputFormat::Json`] is the response's JSON object, the `structured_content` companion of the text:
    /// `{"body", "error": {"code", "message", "causes", "retryable"}, "hints", "recovery", "isError": true}`, where
    /// `body` is the text before `help` and `recovery`. `causes`, `hints` and `recovery` are arrays, `[]` when
    /// empty. It is the one error shape: an
    /// `AgentResponse` with an [`error`](crate::AgentResponse::error) writes the same keys.
    #[must_use]
    pub fn render(&self, format: OutputFormat) -> String {
        self.response().render(format)
    }

    /// The response that is this error alone. Its type name never renders: a response with an error has no empty list.
    fn response(&self) -> crate::AgentResponse {
        crate::AgentResponse::new("error").error(self.clone())
    }

    /// Render formatted for GitHub Actions workflow annotations (`::error title=code::message`).
    ///
    /// The message is encoded as GitHub workflow command data: `%` becomes `%25` first, then CR and LF become `%0D`
    /// and `%0A`, so the annotation stays on one line and a literal `%0A` in the message cannot decode to a line
    /// break. The `title` property is encoded the same way plus `:` → `%3A` and `,` → `%2C`.
    #[must_use]
    pub fn render_github_annotation(&self) -> String {
        format!(
            "::error title={}::{}",
            escape_annotation_property(self.code.label()),
            escape_annotation_data(&self.message)
        )
    }

    /// Build an MCP [`CallToolResult`](crate::mcp::CallToolResult) representing this error: the result of
    /// `AgentResponse::new(..).error(self)`.
    ///
    /// Sets `is_error: true`. Text content is `render(OutputFormat::Text)`; `structured_content` is
    /// `render(OutputFormat::Json)`. To report the error next to data (a batch where some operations answered), add
    /// it to that response with [`AgentResponse::error`](crate::AgentResponse::error) instead.
    #[must_use]
    pub fn to_call_tool_result(&self) -> crate::mcp::CallToolResult {
//! `renderHints`, `appendHints` and `renderRecovery`: the `help[]` and `recovery[]` blocks on their own.

use napi::bindgen_prelude::Unknown;
use napi_derive::napi;

use super::input::{self, Budget, List, MAX_HINTS, MAX_STRING_BYTES};

/// A recovery hint for `renderRecovery` and `FailedOp` (JavaScript-friendly — no structured params over this
/// boundary; use `AgentResponse.recoveryHint` for the common case, or the Rust API directly for typed params).
#[napi(object, js_name = "RecoveryHint")]
#[derive(Debug, Clone)]
pub struct JsRecoveryHint {
    /// The tool/operation name the agent should call to recover.
    pub tool: String,
    /// Optional human-readable reason.
    pub reason: Option<String>,
}

impl From<JsRecoveryHint> for crate::recovery::RecoveryHint {
    fn from(h: JsRecoveryHint) -> Self {
        let hint = Self::new(h.tool);
        match h.reason {
            Some(reason) => hint.reason(reason),
            None => hint,
        }
    }
}

/// Render the TOON 4.4 inline array `help[N]: h1,h2` (no trailing newline).
///
/// # Errors
///
/// Returns an error if `hints` exceeds `MAX_HINTS` entries, a hint exceeds 1 MiB, or the call's strings exceed
/// the call's byte cap (16 MiB) in all.
#[napi(catch_unwind, js_name = "renderHints", ts_args_type = "hints: Array<string>")]
pub fn render_hints(hints: Unknown<'_>) -> napi::Result<String> {
    let mut budget = Budget::new();
    let hints = List::new(hints, "hints")?;
    Ok(hints_block(budget.strings(&hints, "hints", MAX_HINTS, "hint", MAX_STRING_BYTES)?))
}

fn hints_block(hints: Vec<String>) -> String {
    let h: Vec<crate::hints::Hint> = hints.into_iter().map(Into::into).collect();
    crate::hints::render_hints(&h)
}

/// Append the `help[N]: …` block to a TOON document: one LF first unless `body` is empty or ends in one.
///
