#[test]
fn ac021_new_defaults_hints_empty_and_hints_is_a_consuming_builder() {
    let resp = StatusResponse::new("tool", "desc", vec![]);
    assert!(resp.hints.is_empty());

    let hints = vec![Hint::new("a hint")];
